    if ((st == NULL) || (field == NULL) || (cmd == NULL)) {
        return ADCS_E_NULL;
    }

    if (!adcs_is_finite_vec3(field) || !isfinite(time) || !isfinite(alpha) ||
        !isfinite(gain) || !isfinite(limit)) {
        return ADCS_E_RANGE;
    }

    if (alpha < 0.0 || alpha > 1.0 || gain < 0.0 || limit < 0.0) {
        return ADCS_E_RANGE;
    }

    if (st->initialized && time < st->previous_time_s) {
        return ADCS_E_RANGE;
    }

    double b2 = adcs_vec3_dot(field, field);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        cmd->command = (adcs_vec3_t){0, 0, 0};
        cmd->saturated_axes = 0U;
        return ADCS_E_DEGENERATE;
    }

    adcs_vec3_t delta, raw_rate, new_part, old_part;

    if (!st->initialized) {
        st->previous_field_t = *field;
        st->previous_time_s = time;
        st->initialized = 1;
        *rate = (adcs_vec3_t){0, 0, 0};
    } else {
        double dt = time - st->previous_time_s;
        delta = adcs_vec3_sub(field, &st->previous_field_t);
        raw_rate = adcs_vec3_scale(&delta, 1.0 / dt);

        new_part = adcs_vec3_scale(&raw_rate, alpha);
        old_part = adcs_vec3_scale(rate, 1.0 - alpha);

        *rate = adcs_vec3_add(&new_part, &old_part);

        st->previous_field_t = *field;
        st->previous_time_s = time;
    }

    double parallel_coeff = adcs_vec3_dot(rate, field) / b2;
    adcs_vec3_t parallel_part = adcs_vec3_scale(field, parallel_coeff);
    adcs_vec3_t perp = adcs_vec3_sub(rate, &parallel_part);

    adcs_vec3_t command = adcs_vec3_scale(&perp, -gain);

    unint32 sat_axes = 0U;
    double vals[3] = {command.x, command.y, command.z};

    for (size_t i = 0; i < 3; i++) {
        if (fabs(vals[i]) > limit) {
            vals[i] = copysign(limit, vals[i]);
            sat_axes |= (unint32)(1U << i);
        }
    }

    cmd->command = (adcs_vec3_t){vals[0], vals[1], vals[2]};
    cmd->saturated_axes = sat_axes;

    return ADCS_OK;
}

